      "ホーム画面タップ１": "吾の足元に跪き、もっと吾の名である｢カエサル大帝｣を呼ぶがよい！なぜそのような事を、だと？お前の口から何度も聞きたいからだ！さあ、もっと呼ぶのだ！",
