      "メインページでタップ３": "うん？なんで触ってくるんだ？分かった！きっと私の体がうらやましいんだろう！",
      "メインページでタップA1": "その目つき…まだ諦めていない様だな！さすがこの真田幸村に付いて来れる者だな！",
      "メインページでタップ-下着1": "やっぱり修行後の休憩時間は一番気持ちいね！",
      "メインページでタップ-下着2": "キャッ！変な所触らないでよ…そんな暇があるなら、私と一緒に修行すれば良いのに…",
      "星アップ": "はは！また強くなった！これでもっと強い者とやり合える！ワクワクするな！",
