    "dialogues": {
      "召喚獲得": "子龍、参上！まぁ、よろしくね！そういえば、可愛い子はどこに居るか知ってるか？",
      "メインページでタップ1": "何故いつも人を助けるのかって？彼女の思うがままに…じゃなくて、彼女達の笑顔が見たいからに決まってるじゃん！",
      "メインページでタップ２": "こう見えても息抜きをする事は得意なんだ！うん？敵陣を攻める事に決まってるじゃん？",
      "メインページでタップ３": "あぁ〜可愛い子と一緒に遊びたいなぁ！茶々のような可愛い子がいればもっといいけど…うっ、よだれ出てきちゃった",
      "メインページでタップA1": "可愛い子〜可愛い子〜♪可愛い子はど･こ･だ〜♪",
      "メインページでタップ-下着1": "この前女の子にやってあげたのはこんな感じじゃなかったはずなのにな…なんか、変だな…",
      "メインページでタップ-下着2": "それ本当に薬なのか？何だかヤバそうな物みたいだけど…",
      "星アップ": "師匠から教わった技がどんどん上手くなったな！",
      "覚醒": "やった！これでもっと美少女達を助けられる！",
      "親密アイテム1": "あれ…なんだ、ベタベタしてて気持ち悪い…傷口に本当に良いのか？",
      "親密アイテム2": "何だかこの光景ヤバそうだね…僕に薬を付けるのが美少女だったらなぁ…君がダメってわけじゃないけど",
      "MVP宣言": "この程度でこの趙子龍は阻めんぞ！",
      "スキル1": "この程度の実力だけか？ふんっ",
      "スキル2": "槍は龍の如く！",
      "奥義1": "女の子の前で恥は晒さないよ！見てな！",
      "奥義2": "「子龍」の龍は、空飛ぶ昇龍なり！",
      "死亡SE": "うあああ！"
    },
