      "パンツの紐を引っ張る": "やぁん、城主様のいじわる…。今はプールのお時間ですのに…。",
      "頭をタップ": "今日は城主様と一緒にリラックスして楽しみます。",
      "胸をタップ": "僭越ながら、本日は私がコーチを…あっ、うぅ～",
