    "title": "SSR/SSR呂布",
    "rarity": "SSR",
    "type": "力",
    "role": "強力斬殺、無双武神",
    "cv": "暁鞠子",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA2MjlfMTQ0/MDAxNjg4MDIyNjUzNDk0.QpvG1-w7C8MyHX5tF5wbr_lfH9VT117_jNz_Bm6DlcIg.mtW-SgKnca14YjnilgU21gLhs83U0cQYO_DbbsCUVicg.JPEG/%EC%97%AC%ED%8F%AC.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "俺様は天下無敵の呂布だ！…貂蝉俺は絶対にお前を見つける。",
      "ホーム画面タップ１": "天下無双の俺様と戦いたいのか？フハハ…俺は手加減しねぇぞ！",
      "ホーム画面タップ２": "相棒のためなら甘んじて一切を犠牲にしても構わん。全てを捧げることこそ、本物の友情だ！そう思わんか？",
      "ホーム画面タップ３": "貂蝉…貂蝉…一体どこだ？お前がいない日々…本当に寂しい…寂しいぞ！",
      "ホーム画面下着状態": "はぁ…このマッサージ、めっちゃ気持ちいいな…ああ…今度は俺様がマッサージしてやるぞ！",
      "ホーム画面下着タップ1": "貂蝉もこんなマッサージを楽しめたらいいのになぁ、今どこにいるんだろう？",
      "ホーム画面下着タップ2": "あ…これは…気持ちいいぞ！もっと、もっと！もっとやってくれ！うん…気持ちいいさ！",
      "ランクアップ": "雑魚どもとの差がどんどん大きくなったか？ちょうどいい！",
      "覚醒": "ふむ…この世に俺様の相手になれる者はもういないのか？",
      "調教道具1": "------------------------------",
      "MVP宣言": "無敵である俺様にとっては、楽勝だ！",
      "プレゼント-挨拶": "よ！来てくれたか？",
      "プレゼント-感謝1": "必ず恩返しするよ",
      "プレゼント-感謝2": "ありがとう！",
      "プレゼント-感謝3": "嬉しいぞ！",
      "クローズアップ": "------------------------------",
      "スキル1": "ヘイヤ！",
      "スキル2": "ヒャッ！",
      "スキル3": "死ね！",
      "奥義1": "オラオラオラ…皆消えろ雑魚どもめ！",
      "奥義2": "ハハハ…俺様の全力の一撃を受け止められるか？",
      "死亡": "そんな…バカな"
    },
