    "title": "SSR/SSR佐々木小次郎",
    "rarity": "SSR",
    "type": "力",
    "role": "影の鎧、鉄壁反撃",
    "cv": "神代そら",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA2MjlfMjUx/MDAxNjg4MDI1MjE1OTk4.CcXOBCR82V69JTates8mOuSgoRMRQBMKfvkBGY0-h1wg.j2SW6Ead4RL4Bdss30Putj8i31Nx5KB18Br5gRFGJGQg.JPEG/%EC%82%AC%EC%82%AC%ED%82%A4%EC%BD%94%EC%A7%80%EB%A1%9C.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "拙者は剣士、佐々木小次郎でござる。閣下も私のロックチームに加入したいのか？",
      "ホーム画面タップ１": "あ、武蔵様！武蔵様は今、何をしているのだろう、えっへへ～",
      "ホーム画面タップ２": "拙者の手料理が食べりたい？自慢話じゃないけど、拙者の手料理が半端ないでござるよ？",
      "ホーム画面タップ３": "何故この刀が長船って？閣下がこの刀が、船のように長く見えないでござるか？",
      "ホーム画面下着状態": "ほら、心配しないで。痛くないから",
      "ホーム画面下着タップ1": "えっへ、お姉さんが優しく注射してあげよう、お、と、う、と、くん",
      "ホーム画面下着タップ2": "あら、勝手に動かないで、違うところに注射しちゃうから",
      "ランクアップ": "う、なんか武蔵様に一歩近づいた気がするね！",
      "覚醒": "武蔵様！",
      "調教道具1": "------------------------------",
      "MVP宣言": "こんな派手なやり方なら、彼女に気づかれるかな？",
      "プレゼント-挨拶": "うぅ、武蔵様はまだ？",
      "プレゼント-感謝1": "あ、ありがとう。",
      "プレゼント-感謝2": "今度は美味しい食べ物を奢ってあげるよ。",
      "プレゼント-感謝3": "あなた、優しいね",
      "クローズアップ": "------------------------------",
      "スキル1": "エイ！",
      "スキル2": "ハ！…",
      "スキル3": "エイハ！",
      "奥義1": "フフ、死の舞を、見せてあげよう",
      "奥義2": "フフ、月の寒さを感じてもらおう",
      "死亡": "やはり、武蔵様に追いつかないのか"
    },
