      "スキル1": "ヘイヤ！",
      "スキル2": "倒せ！",
      "スキル3": "さようなら！",
      "奥義1": "私をなめるなよ！",
      "奥義2": "義経様の為に戦います！",
      "死亡": "もう義経様に会えないですね、う～"
